/* ОБРАБОТКА ЗНАЧЕНИЙ. Приводит в порядок выделенные клетки: регистр, пробелы,
   переносы, текст в число и обратно, замена (в том числе по образцу), приставка
   и окончание. Перед записью показывает ПРЕДПРОСМОТР первых строк — видно, что
   получится, до того как это случится с тысячей клеток.

   Читает и пишет по запросу, поэтому работает и на больших областях: снимок
   книги плагину не нужен. */

const ДЕЛА = {
  'ВЕРХНИЙ РЕГИСТР':      т => т.toUpperCase(),
  'нижний регистр':       т => т.toLowerCase(),
  'Как в предложении':    т => т.toLowerCase().replace(/(^|[.!?…]\s+)([a-zа-яё])/g, (в, п, з) => п + з.toUpperCase()),
  'Каждое Слово С Большой': т => т.toLowerCase().replace(/(^|[\s(«\"'-])([a-zа-яё])/g, (в, п, з) => п + з.toUpperCase()),
  'Обрезать пробелы по краям': т => т.replace(/^[\s ]+|[\s ]+$/g, ''),
  'Схлопнуть двойные пробелы': т => т.replace(/[  \t]{2,}/g, ' '),
  'Убрать все пробелы':   т => т.replace(/[\s ]+/g, ''),
  'Убрать переносы строк': т => т.replace(/[\r\n]+/g, ' ').replace(/ {2,}/g, ' '),
  'Убрать неразрывные пробелы': т => т.replace(/ /g, ' '),
  'Только цифры':         т => т.replace(/[^\d,.-]/g, ''),
};

/* Особые действия считаются отдельно: они смотрят не только на текст. */
function применить(з, п){
  const дело = п.дело;
  if(дело === 'Текст в число'){
    if(typeof з === 'number') return з;
    const т = String(з === null || з === undefined ? '' : з).replace(/[\s ]/g, '').replace(',', '.');
    const ч = parseFloat(т);
    return т !== '' && isFinite(ч) && /^-?\d*\.?\d+(e[+-]?\d+)?$/i.test(т) ? ч : з;
  }
  if(дело === 'Число в текст') return з === null || з === undefined ? з : String(з);
  if(дело === 'Округлить'){
    if(typeof з !== 'number') return з;
    const к = Math.pow(10, Math.max(0, Math.min(10, +п.знаков || 0)));
    return Math.round(з * к) / к;
  }
  if(з === null || з === undefined || з === '') return з;
  const текст = String(з);
  if(дело === 'Приставка и окончание') return (п.приставка || '') + текст + (п.окончание || '');
  if(дело === 'Заменить'){
    const что = String(п.найти || '');
    if(!что) return з;
    let правило;
    try {
      const тело = п.образцом ? что : что.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
      правило = new RegExp(тело, п.регистр ? 'g' : 'gi');
    } catch(e){ return з; }
    return текст.replace(правило, String(п.заменить === undefined ? '' : п.заменить));
  }
  const f = ДЕЛА[дело];
  return f ? f(текст) : з;
}

async function Предпросмотр(){
  const п = параметры({}), в = книга.выделение;
  if(!в){ панель.список('образец', [['', 'выделите клетки']]); return; }
  const строки = await лист(в.лист).прочитать(в.область);
  const ряды = [];
  for(const р of строки){
    for(const з of р){
      if(ряды.length >= 8) break;
      if(з === null || з === undefined || з === '') continue;
      ряды.push([String(з).slice(0, 40), String(применить(з, п)).slice(0, 40)]);
    }
    if(ряды.length >= 8) break;
  }
  панель.список('образец', ряды.length ? ряды : [['', 'в выделении нечего менять']]);
}

async function Применить(){
  const п = параметры({}), в = книга.выделение;
  if(!в){ панель.сообщение('Сначала выделите клетки'); return; }
  const строки = await лист(в.лист).прочитать(в.область);
  let тронуто = 0;
  const новые = строки.map(р => р.map(з => {
    const стало = применить(з, п);
    if(стало !== з) тронуто++;
    return стало;
  }));
  if(!тронуто){ панель.сообщение('Ничего не изменилось: ' + в.область); return; }
  лист(в.лист).диапазон(в.область).записать(новые);
  панель.сообщение('«' + п.дело + '»: изменено клеток ' + тронуто + ' в ' + в.область);
  Предпросмотр();
}

function Старт(){ Предпросмотр(); }
function ПриВыделении(){ Предпросмотр(); }
